<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Piet Mondrian, 1930</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;700;900&family=Archivo+Black&display=swap" rel="stylesheet">
<style>
  :root{
    --red:#d9332a;
    --blue:#21489e;
    --yellow:#f4c324;
    --black:#111111;
    --white:#f6f3ec;
    --grey:#c9c6be;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{background:var(--white);color:var(--black);font-family:'Archivo',sans-serif;line-height:1.5;-webkit-font-smoothing:antialiased}
  ::selection{background:var(--yellow);color:var(--black)}

  .frame{max-width:1200px;margin:0 auto;padding:0 24px}

  header{display:flex;justify-content:space-between;align-items:center;padding:22px 24px;border-bottom:5px solid var(--black)}
  .logo{font-family:'Archivo Black',sans-serif;font-size:1.05rem;letter-spacing:.08em;text-transform:uppercase;text-decoration:none;color:var(--black);display:flex;align-items:center;gap:12px}
  .logo-mark{display:grid;grid-template-columns:14px 14px;grid-template-rows:14px 14px;width:14px;height:14px;gap:2px;outline:2px solid var(--black)}
  .logo-mark i:nth-child(1){background:var(--white)}
  .logo-mark i:nth-child(2){background:var(--red)}
  .logo-mark i:nth-child(3){background:var(--blue)}
  .logo-mark i:nth-child(4){background:var(--yellow)}
  nav{display:flex;gap:26px;font-size:.78rem;font-weight:700;text-transform:uppercase;letter-spacing:.12em}
  nav a{color:var(--black);text-decoration:none;border-bottom:3px solid transparent;padding-bottom:2px}
  nav a:hover{border-color:var(--red)}

  /* hero */
  .hero{display:grid;grid-template-columns:1.05fr 1fr;min-height:86vh;border-bottom:5px solid var(--black)}
  .hero-copy{display:flex;flex-direction:column;justify-content:center;padding:56px 48px;border-right:5px solid var(--black)}
  .kicker{font-size:.75rem;font-weight:900;letter-spacing:.3em;text-transform:uppercase;display:flex;align-items:center;gap:14px}
  .kicker::before{content:"";width:44px;height:5px;background:var(--red)}
  h1{font-family:'Archivo Black',sans-serif;font-size:clamp(2.4rem,4.6vw,4.2rem);line-height:.98;text-transform:uppercase;margin:22px 0 18px;letter-spacing:-.01em}
  h1 .yr{color:var(--blue)}
  .lede{font-size:1.12rem;max-width:44ch;font-weight:500}
  .meta-row{display:flex;flex-wrap:wrap;gap:10px 26px;margin-top:28px;font-size:.82rem;font-weight:700;text-transform:uppercase;letter-spacing:.1em}
  .meta-row span b{display:block;font-family:'Archivo Black',sans-serif;font-size:1.15rem;letter-spacing:0;text-transform:none;margin-top:2px}
  .cta-row{display:flex;gap:14px;margin-top:34px;flex-wrap:wrap}
  .btn{display:inline-block;font-weight:900;text-transform:uppercase;letter-spacing:.12em;font-size:.8rem;padding:16px 26px;text-decoration:none;border:4px solid var(--black);color:var(--white);transition:transform .15s, box-shadow .15s}
  .btn-primary{background:var(--black);color:var(--yellow)}
  .btn-ghost{background:transparent;color:var(--black)}
  .btn:hover{transform:translate(-3px,-3px);box-shadow:6px 6px 0 var(--red)}

  .hero-art{position:relative;background:var(--white);overflow:hidden}
  .composition{position:absolute;inset:0;margin:auto;background:var(--white);outline:5px solid var(--black)}
  .composition .bar{position:absolute;background:var(--black)}
  .fill-red{position:absolute;background:var(--red)}
  .fill-blue{position:absolute;background:var(--blue)}
  .fill-yellow{position:absolute;background:var(--yellow)}

